DROP TABLE IF EXISTS `clinic_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `clinic_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `last_name` varchar(255) NOT NULL,
  `first_name` varchar(255) NOT NULL,
  `last_kana` varchar(255) NOT NULL,
  `first_kana` varchar(255) NOT NULL,
  `birthday` date DEFAULT NULL,
  `age` int(11) NOT NULL,
  `gender_id` int(11) DEFAULT NULL,
  `postal_code` varchar(255) NOT NULL,
  `address_1` varchar(255) NOT NULL,
  `address_2` varchar(255) NOT NULL,
  `address_3` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `cell_phone` varchar(255) DEFAULT NULL,
  `fax` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `housecall_distance` int(11) DEFAULT NULL,
  `housecall_additional_distance` int(11) DEFAULT NULL,
  `is_redeemed` tinyint(1) DEFAULT NULL,
  `application_count` int(11) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `clinic_users_gender_FK` (`gender_id`),
  CONSTRAINT `clinic_users_gender_FK` FOREIGN KEY (`gender_id`) REFERENCES `gender` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='利用者';
/*!40101 SET character_set_client = @saved_cs_client */;

